  function sourcePlanPrices(){const values={};for(const key of ['lpPc','lpCtn','disc1','disc2','disc3']){const field=document.querySelector('#sourcePrice-'+key);if(!field)return null;values[key]=field.value.trim()===''?NaN:Number(field.value)/(key==='disc1'||key==='disc2'?100:1);}return values;}
