  function previewPlan(){
    const row=data.tasks.find(row=>row.id===dialogContext?.taskId);if(!row)return;
    const capacity=sourceDemandCapacity(row),value=Number(document.querySelector('#planTotal').value),valid=Number.isSafeInteger(value)&&value>=1&&value<=9999,extra=valid?Math.max(0,value-capacity):0;
    document.querySelector('#planCustomerResult').textContent=valid?qtyDigits(Math.min(value,capacity))+' CTN':'—';
    document.querySelector('#planStockResult').textContent=valid?qtyDigits(extra)+' CTN':'—';
    document.querySelector('#planExtraOptions').hidden=!valid||extra===0;
    document.querySelector('#planExtraLabel').textContent='多出的 '+qtyDigits(extra)+' 箱来自哪里？ *';
    const unchanged=Boolean(row.procurement?.revision)&&value===row.procurement.totalCtn&&document.querySelector('#planTransport').value===(row.procurement.transportMode||'');
    document.querySelector('#planExcess').textContent=!valid?'请输入 1–9999 箱；供货不足不改变客户需求。':unchanged?'当前已保存的供货数量；修改数字后才能再次保存。':extra>0?'多出的 '+qtyDigits(extra)+' 箱将进入 Keeped Stock；仓库收货后才可分配。':value<capacity?'扣除其他来源后仍需采购 '+qtyDigits(capacity-value)+' 箱；客户需求保持不变。':'实际到货后由采购员分配给客户。';
    document.querySelector('#saveSupplierPlan').disabled=!valid||unchanged||!['SUPPLIER_DELIVER','SELF_COLLECT'].includes(document.querySelector('#planTransport').value)||!document.querySelector('#planReason').value.trim()||(extra>0&&(!['FREE_GOODS','PAID_EXTRA'].includes(document.querySelector('#planExtraKind').value)||!document.querySelector('#planConfirmExtra').checked))||(row.po&&!document.querySelector('#planSupplierConfirmed').checked);
  }
