  function poSelectionIssue(row){
    if(view!=='active'||!selected.size||selected.has(row?.id))return '';
    const chosen=data.tasks.filter(item=>selected.has(item.id)),first=chosen[0];
    if(!row||!first)return '请先清除选择，再核对采购来源。';
    if(savePending||drafts.size||sequenceDraft)return '请先保存或取消当前修改，再选择合单来源。';
    for(const item of [...chosen,row]){
      const handoff=poData?.orders.find(order=>order.taskIds.includes(item.id))?.procurementHandoff;
      if(item.archived||item.salesInvoiceLocked||item.salesInvoiceNumber||handoff&&handoff.stage!=='LEGACY'&&!handoff.editable)return '已开票、归档或被财务锁定的来源不能合并。';
      if(allocationUi()?.sourceDirty(item.id))return '请先保存采购来源的修改，再合并 P.O.。';
      if(!item.supplierId||!data.suppliers.some(supplier=>supplier.id===item.supplierId)||!Number.isSafeInteger(item.procurement?.totalCtn)||item.procurement.totalCtn<1||!Number.isFinite(item.netCostCtn)||item.netCostCtn<0)return '请先保存供应商、采购数量及成本，再合并 P.O.。';
    }
    if(row.supplierId!==first.supplierId)return '只能选择同一供应商的采购来源。';
    if((row.po||'')!==(first.po||''))return '已有 P.O. 的来源不能与其他采购单混选。';
    return '';
  }
  function poDialog(id,editNumber=false){if(savePending){showStatus(saveDiagnostic(savePending,'请先核对原保存，新的 P.O. 操作尚未开始。'),true);return;}if(drafts.size||sequenceDraft){showStatus('请先保存或取消当前价格和排列修改。',true);return;}const chosen=data.tasks.find(row=>row.id===id);if(!chosen)return;if(chosen.po&&!editNumber){if(allocationUi()?.sourceDirty(id)){showStatus('此采购来源有未保存修改，请先保存该来源；其他草稿保留。',true);return;}return reviewPo(id);}if(selected.size&&!selected.has(id)){showStatus('请点击已勾选行的 P.O. 输入框，或先清除选择。',true);return;}const rows=selected.size?data.tasks.filter(row=>selected.has(row.id)):[chosen];if(rows.some(row=>allocationUi()?.sourceDirty(row.id))){showStatus('此采购来源有未保存修改，请先保存该来源；其他草稿保留。',true);return;}if(new Set(rows.map(row=>row.supplierId)).size!==1||rows.some(row=>!row.supplierId)){showStatus('一张 P.O. 可包含不同客户，但必须属于同一供应商。',true);return;}if(rows.some(row=>!Number.isSafeInteger(row.procurement?.totalCtn)||row.procurement.totalCtn<1||!Number.isFinite(row.netCostCtn)||row.netCostCtn<0)){showStatus('请先在 Supplier 弹窗保存采购数量及成本，再开 P.O.。',true);return;}const existingPo=[...new Set(rows.map(row=>row.po))],prefill=existingPo.length===1&&existingPo[0]?existingPo[0]:company+'-PO-';
    const count=new Set(rows.map(row=>JSON.stringify([row.barcode,row.packing]))).size,total=window.purchaseTaskGrid.totals(rows).amount;
    dialogContext={kind:'po',taskIds:rows.map(row=>row.id)};formDialog(editNumber&&chosen.po?'Edit P.O. No. 修改采购单号':'Purchase Order 创建采购单',supplierName(chosen.supplierId),`<div class="po-purpose">确认供应商、客户用途、数量和金额后，将明细合并采购，使用同一份 P.O.。</div><div class="po-confirm-overview"><div class="po-number-entry"><label for="poNumber">OUR P.O. 我们的采购单号 *</label><input id="poNumber" maxlength="80" value="${esc(prefill)}" placeholder="${company}-PO-000000" autocomplete="off"></div><div class="po-confirm-totals"><div><span>QTY</span><strong>${qtyDigits(rows.reduce((n,row)=>n+(row.procurement?.totalCtn??row.ord),0))} CTN</strong></div><div><span>Amount</span><strong>MYR ${num(total)}</strong></div></div></div><div class="po-items-summary">${count} Items · ${new Set(rows.map(row=>row.customerId)).size} Customers</div><table class="rowlist po-items"><thead><tr><th>Customer</th><th>Description</th><th>Qty</th><th>Net Cost</th><th>Line Cost</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(data.customers.find(c=>c.id===row.customerId)?.shortName||data.customers.find(c=>c.id===row.customerId)?.name||row.customerId)}</td><td class="po-barcode"><b>${esc(row.name)}</b><small>${esc(row.barcode)} · ${esc(row.packing)}</small></td><td class="po-quantity">${qtyDigits(row.procurement?.totalCtn??row.ord)}</td><td class="amount">${num(row.netCostCtn)}</td><td class="amount">${num(window.purchaseTaskGrid.totals([row]).amount)}</td></tr>`).join('')}</tbody></table>`,'<button class="btn primary" id="savePo">Confirm P.O. 确认采购单</button>','po',company+' · '+supplierName(chosen.supplierId));

  }

  function companyName(){return company==='NCT'?'North Cape Trading':'Global HR';}
  const selected = new Set();
